int uv_thread_getpriority(uv_thread_t tid, int* priority) {
  DWORD err;
  int r;

  if (priority == NULL)
    return UV_EINVAL;

  r = GetThreadPriority(tid);
  if (r == THREAD_PRIORITY_ERROR_RETURN) {
    err = GetLastError();
    if (err == ERROR_INVALID_HANDLE)
