/** Creates a Lit reactive controller that subscribes the host to a single query. The returned accessor is callable and also exposes `current`, `refetch`, `suspense`, and `destroy`. When `options` is a function, it is re-read during host updates so query keys and options can follow reactive host state. If `queryClient` is omitted, the controller resolves the client from the nearest connected `QueryClientProvider`. */
export function createQueryController<
  TQueryFnData = unknown,
  TError = DefaultError,
  TData = TQueryFnData,
  TQueryData = TQueryFnData,
  TQueryKey extends QueryKey = QueryKey,
>(
  host: ReactiveControllerHost,
  options: Accessor<
    CreateQueryOptions<TQueryFnData, TError, TData, TQueryData, TQueryKey>
  >,
  queryClient?: QueryClient,
): QueryResultAccessor<TData, TError> {
  const controller = new QueryController(host, options, queryClient)

  return Object.assign(
    createValueAccessor(() => controller.readCurrent()),
    {
      refetch: controller.refetch,
      suspense: controller.suspense,
      destroy: () => controller.destroy(),
