/** Returns a new array with `item` added at the end. If that makes the array longer than `max`, the first item is dropped. Only one item is dropped, so the result can still exceed `max` if `items` already did. */
export function addToEnd<T>(items: Array<T>, item: T, max = 0): Array<T> {
  const newItems = [...items, item]
  return max && newItems.length > max ? newItems.slice(1) : newItems
