        if (method_exists($this->grammar, $method) || $this->grammar::hasMacro($method)) {
            if ($this->hasState()) {
                $this->state->update($command);
            }

            if (! is_null($sql = $this->grammar->$method($this, $command))) {
                $statements = array_merge($statements, (array) $sql);
            }
        }
    }

    return $statements;
}
