    while (!remaining.IsEmpty && remaining[0] == ' ')
    {
        remaining = remaining[1..];
    }

    if (remaining.IsEmpty)
    {
        Current = default;
        return false;
    }

    var separatorIndex = remaining.IndexOf(' ');
    if (separatorIndex < 0)
    {
        Current = remaining;
        remaining = [];
        return true;
    }

    Current = remaining[..separatorIndex];
    remaining = remaining[(separatorIndex + 1)..];
    return true;
}
