public Ttl GetTtl(Context context, object? result)
{
    if (context is null)
    {
        throw new ArgumentNullException(nameof(context));
    }

    if (!context.ContainsKey(TimeSpanKey))
    {
        return NoTtl;
    }

    bool sliding = false;

