/** Replaces the identifier for the root path key of a member expression For dot notation like `rootKey.x.y.z` the AST is constructed with the `rootKey` being nested deep inside a wrapper MemberExpression holding `rootKey.x` and so on This function helps replace the `rootKey` identifier with the provided identifier node */
export function replaceMemberExpressionRootIndentifier(
