```typescript
/** Pairs each dynamic `import()` with the `__VITE_PRELOAD__` marker that belongs to it. Each import is wrapped as `__vitePreload(factory, __VITE_PRELOAD__)`, so its marker comes right after it. Nested imports nest the wrappers, so the imports and markers form balanced brackets. For example, in `import('a').then(() => import('b'))`, b's marker ends up before a's. Pairing each import with the next marker would give b's marker to both imports and drop a's CSS to `void 0` (#22700). Instead the markers are matched with a stack in one pass, and each marker closes the innermost import that is still open. The returned array is parallel to `imports`. Entry `i` holds the start position of import `i`'s marker, or -1 when the import has no marker. */
export function matchImportsToPreloadMarkers(
  code: string,
  imports: readonly ImportSpecifier[],
): number[] {
  const importMarkerPos = new Array<number>(imports.length).fill(-1)
  if (imports.length === 0) return importMarkerPos

  const openImports: number[] = []
  let nextImport = 0
  for (
    let markerStartPos = findPreloadMarker(code, imports[0].e);
    markerStartPos !== -1;
    markerStartPos = findPreloadMarker(
      code,
      markerStartPos + preloadMarker.length,
    )
  ) {
    while (
      nextImport < imports.length &&
      imports[nextImport].e <= markerStartPos
    ) {
      openImports.push(nextImport++)
    }
    if (openImports.length) {
      importMarkerPos[openImports.pop()!] = markerStartPos
    }
  }
  // #3051: a lone import whose marker isn't placed after it pairs with the only marker
  if (imports.length === 1 && importMarkerPos[0] === -1) {
    importMarkerPos[0] = findPreloadMarker(code)
  }

  return importMarkerPos
}
