public static Range<A> fromCount<A>(A min, A count, A step)
    where A : INumberBase<A>,
              IComparisonOperators<A, A, bool>
{
    var max = min + (count * step - step);
    return new(min, max, step, Go());

    IEnumerable<A> Go()
    {
        var c = count;
        for (var x = min; c != A.Zero; x += step, c -= A.One)
