  for (var i = 0; i < text.length; i++) {
    var chain = _data[text.codeUnitAt(i)];
    var iNext = i;
    var resolvedGlyph = chain?.glyph;
    for (var j = i + 1; j < text.length; j++) {
      if (chain?.followOn == null) {
        break;
