  struct poll_ctx* ctx;

  ctx = container_of(timer, struct poll_ctx, timer_handle);
  assert(ctx->parent_handle != NULL);
  /* Another due timer may have stopped or restarted the handle. */
  if (ctx->parent_handle->poll_ctx != ctx ||
