```typescript
/** Runs the storage engine. Resolves `ABORTED` when `@fastify/multipart` destroys the file stream mid-way (it does so, without an error, when the client disconnects or a limit is hit), because a storage engine waiting for `end` would otherwise never call back. The actual reason is then read from the parts iterator. A stream destroyed with an error was destroyed by the engine (e.g. by a `pipeline()` to a file that cannot be written), which reports that error itself. Whatever the engine stores after an abort is removed once it calls back, as multer does: what it stored when it succeeds, and the file at `path` (which engines set before writing, by multer's convention) when it fails. */
function storeFile(
  storage: MultipartStorageEngine,
  req: FastifyRequest,
  file: IncomingMultipartFile,
) {
  return new Promise<Partial<UploadedMultipartFile> | typeof ABORTED>(
    (resolve, reject) => {
      const stream = file.stream;
      if (stream.destroyed) {
        return resolve(ABORTED);
      }
      let aborted = false;
      const onClose = () => {
        if (!stream.readableEnded && !stream.errored) {
          aborted = true;
          resolve(ABORTED);
        }
      };
      stream.once('close', onClose);
      storage._handleFile(req, file, (err, info) => {
        stream.off('close', onClose);
        if (!aborted) {
          return err ? reject(err) : resolve(info ?? {});
        }
        const stored = Object.assign(
          file,
          err ? {} : info,
        ) as unknown as UploadedMultipartFile;
        if (!err || stored.path) {
          removeFiles(storage, req, [stored]).catch(() => undefined);
        }
      });
    },
  );
}
