```typescript
/** Track array iteration and return: - if input is reactive: a cloned raw array with reactive values - if input is readonly: a cloned raw array with readonly values, preserving   reactivity - if input is raw or shallow: the original raw array */
export function reactiveReadArray<T>(array: T[]): T[] {
  const raw = toRaw(array)
  if (raw === array) return raw
  track(raw, TrackOpTypes.ITERATE, ARRAY_ITERATE_KEY)
  if (isShallow(array)) return raw
  if (!isReadonly(array)) return raw.map(toReactive)

  // Preserve proxy layers without checking the array's flags for every element.
  return (
    isReactive(array)
      ? raw.map(item => toReadonly(toReactive(item)))
      : raw.map(toReadonly)
  ) as T[]
}
