        // Drop buffers if over capacity.
        while self._buffers.count > self.capacity {
            self._buffers.removeLast()
        }
        // Reset the last used index.
        if self._lastUsedIndex >= self.capacity {
            self._lastUsedIndex = 0
        }
    }
}
