    return IsAsync
               ? new IterableAsyncEnumerable<A>(IO.lift(goAsync))
               : new IterableEnumerable<A>(IO.lift(goSync));

    IEnumerable<A> goSync(EnvIO env)
    {
        var isFirst = true;
        foreach(var item in AsEnumerable(env.Token))
        {
            if (!isFirst)
            {
                yield return value;
            }

            yield return item;
            isFirst = false;
