    let handshakeTypeAndLength: UInt32 = buffer.readInteger()!
    let handshakeType: UInt8 = UInt8((handshakeTypeAndLength & 0xFF00_0000) >> 24)
    let handshakeLength: UInt32 = handshakeTypeAndLength & 0x00FF_FFFF
