public string HumanizeWithUnitSystem(
    ByteSizeUnitSystem unitSystem,
    string? format = null,
    TimeUnit timeUnit = TimeUnit.Second,
    CultureInfo? culture = null)
{
    if (unitSystem == ByteSizeUnitSystem.Legacy)
    {
