    option.pluginDefaults = Object.fromEntries(
      plugins
        .filter((plugin) => plugin.defaultOptions?.[option.name] !== undefined)
        .map((plugin) => [plugin.name, plugin.defaultOptions[option.name]]),
    );

    options.push(option);
  }

  return { languages, options };
