/** Convert an array of dot-path strings into a nested object structure. Example: `["profile", "posts.comments"]` becomes `{ profile: true, posts: { comments: true } }` */
function convertRelationsArrayToObject(values: string[]): NestedObject {
    const result: NestedObject = {}

    for (const val of values) {
        const parts = val.split(".")
        let current: NestedObject = result
        for (let i = 0; i < parts.length; i++) {
            const part = parts[i]
            if (i === parts.length - 1) {
                current[part] ??= true
            } else {
                if (current[part] === undefined || current[part] === true) {
                    current[part] = {}
                }
                current = current[part]
            }
        }
    }

    return result
}
