/// Notifies the [Bloc] of a new [event] which triggers all corresponding [EventHandler] instances. registered for the incoming [event]. [event] will not be processed.
void add(Event event) {
  // ignore: prefer_asserts_with_message
  assert(() {
    final handlerExists = _handlers.any((handler) => handler.isType(event));
    if (!handlerExists) {
      final eventType = event.runtimeType;
      throw StateError(
        '''add($eventType) was called without a registered event handler.\n'''
        '''Make sure to register a handler via on<$eventType>((event, emit) {...})''',
      );
    }
    return true;
  }());
  try {
    onEvent(event);
    _eventController.add(event);
  } catch (error, stackTrace) {
    onError(error, stackTrace);
    rethrow;
  }
}
