/** Stringify metadata for deps cache. Remove processing promises and individual dep info browserHash. Once the cache is reload the next time the server start we need to use the global browserHash to allow long term caching */
function stringifyDepsOptimizerMetadata(
  metadata: DepOptimizationMetadata,
  depsCacheDir: string,
) {
  const { hash, configHash, lockfileHash, browserHash, optimized, chunks } =
    metadata
  return JSON.stringify(
    {
      hash,
      configHash,
      lockfileHash,
      browserHash,
      optimized: Object.fromEntries(
        Object.values(optimized).map(
          ({ id, src, file, fileHash, needsInterop, isDynamicEntry }) => [
            id,
            {
              src,
              file,
              fileHash,
              needsInterop,
              isDynamicEntry,
            },
          ],
        ),
      ),
      chunks: Object.fromEntries(
        Object.values(chunks).map(({ id, file, isDynamicEntry }) => [
          id,
          { file, isDynamicEntry },
        ]),
      ),
    },
    (key: string, value: string) => {
      // Paths can be absolute or relative to the deps cache dir where
      // the _metadata.json is located
      if (key === 'file' || key === 'src') {
        return normalizePath(path.relative(depsCacheDir, value))
      }
      return value
    },
    2,
  )
}
