{
    static $manifests = [];

    if (! str_starts_with($path, '/')) {
        $path = "/{$path}";
    }

    if ($manifestDirectory && ! str_starts_with($manifestDirectory, '/')) {
        $manifestDirectory = "/{$manifestDirectory}";
    }

