        if (! empty($customUrl)) {
            return new HtmlString("{$customUrl}{$path}");
        }

        if (Str::startsWith($url, ['http://', 'https://'])) {
            return new HtmlString(Str::after($url, ':').$path);
        }

        return new HtmlString("//localhost:8080{$path}");
