public static A await<A>(Task<A> operation)
{
    SpinWait sw = default;
    while (true)
    {
        if (operation.IsCanceled)
        {
            throw new OperationCanceledException();
        }
        else if (operation.IsFaulted)
        {
            operation.Exception.Rethrow();
        }
