```csharp
/// <summary>Fold the sequence until the predicate returns `true` or the sequence ends</summary>
public S FoldUntil<S>(
    S state,
    Func<S, A, S> f,
    Func<(S State, A Value), bool> predicate)
{
    for(var xs = Clone(); !xs.IsEmpty; xs = xs.Tail)
    {
        state = f(state, xs.Head);
        if (predicate((state, xs.Head))) return state;
    }
    return state;
}
