export function decodePacket (data: any, binaryType?: any, utf8decode?: any): any {
  if (data === undefined) {
    return err;
  }

  let type: string | number;

  // String data
  if (typeof data === 'string') {

    type = data.charAt(0);

    if (type === 'b') {
      return decodeBase64Packet(data.slice(1), binaryType);
    }

    if (utf8decode) {
      data = tryDecode(data);
      if (data === false) {
        return err;
