    case .waitingForMask(let firstByte, let length), .waitingForData(let firstByte, let length, _):
        if length > maxFrameSize {
            throw NIOWebSocketError.invalidFrameLength
        }

        let isControlFrame = (firstByte & 0x08) != 0
