                .names()
                .enumerate()
                .fold(String::new(), |mut seed, (i, name)| {
                    use std::fmt::Write as _;
                    let prefix = if i == 0 { "" } else { ", " };
                    let _ = write!(&mut seed, "{prefix}`{name}`");
                    seed
                });
