    assertThat(list.removeIf(JsonElement::isJsonNull)).isTrue();
    assertThat(a.toString()).isEqualTo("[1,3]");
    assertThat(list.removeIf(element -> false)).isFalse();
    assertThat(a.toString()).isEqualTo("[1,3]");
