/// <summary>Removes the item from the front of the queue atomically</summary>
public A DequeueUnsafe()
{
    SpinWait sw = default;
    while (true)
    {
        var oitems = items;
        if (oitems.IsEmpty) throw Exceptions.SequenceEmpty;
        var top = oitems.Peek();
        var nitems = oitems.Dequeue();
        if (ReferenceEquals(Interlocked.CompareExchange(ref items, nitems, oitems), oitems))
        {
            Dequeued?.Invoke(top);
            return top;
        }
        else
        {
            sw.SpinOnce();
        }
    }
