    var arr = Value;
    if (index < 0 || index > Length) throw new IndexOutOfRangeException(nameof(index));
    if (length == 0)
    {
        return new Arr<A>([valueToInsert]);
    }

    var xs = new A[length + 1];
    xs[index] = valueToInsert;

    if (index != 0)
    {
