/// Tries to find the entity that is colliding with the given entity. It will check if the parent is either a [PropagatingCollisionBehavior] or a [Entity]. If it is neither, it will return [other] or null if [other] is not mounted.
Component? findEntity(PositionComponent other) {
  final parent = other.parent;
  if (!other.isMounted) {
    return null;
  }

  if (parent is! PropagatingCollisionBehavior && parent is! Entity) {
    if (other is ShapeHitbox) {
      return other.parent;
    }
    return other;
  }

  return parent is Entity
      ? parent
      : (parent as PropagatingCollisionBehavior?)?.parent;
}
