/** Takes an abstract syntax tree (AST) and recursively converts it to a document (series of printing primitives). This is done by descending down the AST recursively. The recursion involves two functions that call each other: 1. mainPrint(), which is defined as an inner function here.    It basically takes care of node caching. 2. callPluginPrintFunction(), which checks for some options, and    ultimately calls the print() function provided by the plugin. The plugin function will call mainPrint() again for child nodes of the current node. mainPrint() will do its housekeeping, then call the plugin function again, and so on. All the while, these functions pass a "path" variable around, which is a stack-like data structure (AstPath) that maintains the current state of the recursion. It is called "path", because it represents the path to the current node through the Abstract Syntax Tree. */
async function printAstToDoc(ast, options) {
  ({ ast } = await prepareToPrint(ast, options));

  const cache = new Map();
  const path = new AstPath(ast);

  const ensurePrintingNode = createPrintPreCheckFunction(options);
  const embeds = new Map();

  await printEmbeddedLanguages(path, mainPrint, options, printAstToDoc, embeds);

  // Only the root call of the print method is awaited.
  // This is done to make things simpler for plugins that don't use recursive printing.
  const doc = await callPluginPrintFunction(
    path,
    options,
    mainPrint,
    undefined,
    embeds,
  );

  ensureAllCommentsPrinted(options);

  if (options.cursorOffset >= 0) {
    if (options.nodeAfterCursor && !options.nodeBeforeCursor) {
      return [cursor, doc];
    }
    if (options.nodeBeforeCursor && !options.nodeAfterCursor) {
      return [doc, cursor];
    }
  }

  return doc;

  function mainPrint(selector, args) {
    if (selector === undefined || selector === path) {
      return mainPrintInternal(args);
    }

    if (Array.isArray(selector)) {
      return path.call(() => mainPrintInternal(args), ...selector);
    }

    return path.call(() => mainPrintInternal(args), selector);
  }

  function mainPrintInternal(args) {
    ensurePrintingNode(path);

    const value = path.node;

    if (value === undefined || value === null) {
      return "";
    }

    const shouldCache = isObject(value) && args === undefined;

    if (shouldCache && cache.has(value)) {
      return cache.get(value);
    }

    const doc = callPluginPrintFunction(path, options, mainPrint, args, embeds);

    if (shouldCache) {
      cache.set(value, doc);
    }

    return doc;
  }
}
