        } else {
            let storage = storageRef.takeUnretainedValue()
            return Data(
                bytesNoCopy: UnsafeMutableRawPointer(mutating: ptr.baseAddress!.advanced(by: index)),
                count: Int(length),
                deallocator: .custom { _, _ in withExtendedLifetime(storage) {} }
