/// <summary>
/// Writes the specified end token.
/// </summary>
/// <param name="token">The end token to write.</param>
protected override void WriteEnd(JsonToken token)
{
    switch (token)
    {
        case JsonToken.EndObject:
            _writer.Write('}');
            break;
        case JsonToken.EndArray:
            _writer.Write(']');
            break;
        case JsonToken.EndConstructor:
            _writer.Write(')');
            break;
        default:
