    Sec section = default;
    var (countDelta, newRoot, old) = Root.Remove(key, h, section);
    return ReferenceEquals(newRoot, Root)
               ? (this, Change<V>.None)
               : (new TrieMap<EqK, K, V>(newRoot, count + countDelta), 
                  countDelta == 0
                      ? Change<V>.None
                      : Change<V>.Removed(old!));
