    if (cu == $carriageReturn ||
        cu == $lineFeed ||
        (cu == $slash && nextCodeUnit == $slash)) {
      break;
    }
  }
  pushToken(Token.text(text.substring(position0, position)), position0);
  eatComment();
  eatNewline();
  return true;
}
