/// The smallest rectangle, in world coordinates, that contains every [PositionComponent] in the [world], or null if there is none.
static Rect? worldBounds(World world) {
  Rect? bounds;
  for (final component in world.descendants()) {
    if (component is PositionComponent) {
      final rect = component.toAbsoluteRect();
      bounds = bounds == null ? rect : bounds.expandToInclude(rect);
    }
  }
  if (bounds == null || bounds.isEmpty) {
    return null;
  }
  return bounds;
}
