  if (
    proseWrap !== "always" ||
    path.hasAncestor(
      (node) =>
        SINGLE_LINE_NODE_TYPES.has(node.type) ||
        (node.type === "heading" &&
          (options.parser === "mdx" || !isSetextHeading(node))),
    )
  ) {
