def do_dictsort(value: t.Mapping[K, V], case_sensitive: bool=False, by: 'te.Literal["key", "value"]'='key', reverse: bool=False) -> list[tuple[K, V]]:
    if by == 'key':
        pos = 0
    elif by == 'value':
        pos = 1
    else:
        raise FilterArgumentError('You can only sort by either "key" or "value"')

    def sort_func(item: tuple[t.Any, t.Any]) -> t.Any:
