/** Stops parsing and discards the rest of the body, so that an error response does not race a client that is still uploading (multer does the same before it reports an error). */
export function drainRequest(raw: IncomingMessage): Promise<void> {
  raw.unpipe();
  if (raw.readableEnded || raw.destroyed) {
    return Promise.resolve();
  }
  return new Promise(resolve => {
    const done = () => resolve();
    raw.once('end', done);
    raw.once('close', done);
    raw.once('error', done);
    raw.resume();
  });
}
