    callback: (cache: Accessor<TCache>) => Exclude<T, Function>,
    setter: Setter<T>,
    shouldUpdate: (event: TEvent) => boolean = () => true,
  ) {
    const id = Symbol()
    subscriptions.set(id, {
      shouldUpdate,
      update: (cache) => setter(callback(cache)),
    })
    onCleanup(() => subscriptions.delete(id))
  }

