		t.Error("Route '/PREFIX/XXX' not found via case-insensitive lookup")
	} else if string(out) != "/prefix/xxx" {
		t.Errorf("Wrong result for '/PREFIX/XXX': expected '/prefix/xxx', got: %s", string(out))
