Future<http.Client> getDebouncedHttpClient([Duration? duration]) async {
  // 首先，我们要处理去抖问题。
  var didDispose = false;
  onDispose(() => didDispose = true);

  // 我们将请求延迟 500 毫秒，以等待用户停止刷新。
