          if (part.type === 'field') {
            yield {
              type: 'field',
              fieldname: part.fieldname,
              value: part.value,
              mimetype: 'text/plain',
              encoding: '7bit',
              fieldnameTruncated: !!part.fieldnameTruncated,
              valueTruncated: !!part.valueTruncated,
