/** Ponyfill for [`AbortSignal.any`](https://developer.mozilla.org/en-US/docs/Web/API/AbortSignal/any_static). */
export function abortSignalsAnyPonyfill(signals: AbortSignal[]): AbortSignal {
  if (typeof AbortSignal.any === 'function') {
    return AbortSignal.any(signals);
  }

  const ac = new AbortController();

  for (const signal of signals) {
    if (signal.aborted) {
      trigger();
      break;
    }
    signal.addEventListener('abort', trigger, { once: true });
  }

  return ac.signal;

  function trigger() {
    ac.abort();
    for (const signal of signals) {
      signal.removeEventListener('abort', trigger);
    }
  }
}
