  void operator()(T value) {
    // MSVC2013 fails to compile separate overloads for bool and Char so use
    // std::is_same instead.
    if (!std::is_same<T, Char>::value) {
      if (value == 0 && this->specs.precision == 0)
        return write_zero_with_zero_precision();
      return write(value);
