    itemCount: Int,
    result writeResult: IOResult<Int>
) -> (EventLoopPromise<Void>?, OneWriteOperationResult) {
    switch writeResult {
    case .wouldBlock(0):
        return (nil, .wouldBlock)
    case .processed(let written), .wouldBlock(let written):
        var promise0: EventLoopPromise<Void>?
