```typescript
/** AOT-compile a Zod schema. Returns a clone whose `_zod.run` calls a generated fast path first and falls back to the original runtime parser on failure. - Forward direction only. Backward (encode), async, and `skipChecks` paths   bypass the fast path and use the runtime directly. - Never throws. A schema the fast path can't model is returned unchanged and   keeps using the runtime parser. Pass `{ strict: true }` to get the refusal   as a thrown `ZodCompileUnsupportedError` / `ZodCompileAsyncError` instead. - The original schema is unchanged. The clone shares children by reference. */
export function compile<T extends SomeType>(schema: T, options?: CompileOptions): T {
  try {
    const parser = compileFn(schema);
    const clone = withParser(schema, parser);
    // withParser leaves the parser as its own validator; the generated assert-only variant is better when we have one
    clone._zod.bag.validator = compileValidator(schema, parser as CompiledFn<unknown>);
    return clone;
  } catch (err) {
    if (options?.strict) throw err;
    // a schema we can't compile still has to work, so hand it back untouched on the runtime parser — the same silent fallback global mode already does
    return schema;
  }
}
