    var startIndex = 0
    val lastIndex = path.length - 1

    while (startIndex <= lastIndex) {
        val first = path[startIndex]
        if (first.isPathSeparator()) {
            startIndex++
            continue
        }
        if (first != '.') {
            break
        }

        if (startIndex == lastIndex) {
