std::size_t count_files(const std::string &folder) {
    size_t counter = 0;
    DIR *dp = opendir(folder.c_str());
    if (dp == nullptr) {
        throw std::runtime_error("Failed open folder " + folder);
    }

    struct dirent *ep = nullptr;
    while ((ep = readdir(dp)) != nullptr) {
        if (ep->d_name[0] != '.') counter++;
    }
    (void)closedir(dp);
    return counter;
}
