        assertThat(gson1.fromJson(json, ProtoWithAnnotationsAndJsonNames.class))
            .isEqualTo(gson2.fromJson(json, ProtoWithAnnotationsAndJsonNames.class));
        assertThat(roundTrip(gson1, gson2, json)).isEqualTo(json);
      }
    }
