```typescript
/** Creates a Lit reactive controller that subscribes the host to a mutation. The returned accessor is callable and also exposes `current`, `mutate`, `mutateAsync`, `reset`, and `destroy`. When `options` is a function, it is re-read during host updates so mutation options can follow reactive host state. If `queryClient` is omitted, the controller resolves the client from the nearest connected `QueryClientProvider`. */
export function createMutationController<
  TData = unknown,
  TError = DefaultError,
  TVariables = void,
  TOnMutateResult = unknown,
>(
  host: ReactiveControllerHost,
  options: Accessor<
    CreateMutationOptions<TData, TError, TVariables, TOnMutateResult>
  >,
  queryClient?: QueryClient,
): MutationResultAccessor<TData, TError, TVariables, TOnMutateResult> {
  const controller = new MutationController(host, options, queryClient)

  return Object.assign(
    createValueAccessor(() => controller.current),
    {
      mutate: controller.mutate,
      mutateAsync: controller.mutateAsync,
      reset: controller.reset,
      destroy: () => controller.destroy(),
    },
  )
}
