/** Unwraps common TypeScript expression wrappers around an identifier and returns the identifier's name. Handles `ds as DataSource`, `ds!`, `ds satisfies DataSource`, and the angle-bracket cast `<DataSource>ds`; identifiers reached through these wrappers are tracked alongside bare identifiers so accessor-chain transforms don't miss them. */
const unwrapIdentifierName = (node: ASTNode): string | null => {
    let current: ASTNode = node
    while (true) {
        if (current.type === "Identifier") return current.name
        if (
            current.type === "TSAsExpression" ||
            current.type === "TSNonNullExpression" ||
            current.type === "TSSatisfiesExpression" ||
            current.type === "TSTypeAssertion"
        ) {
            current = current.expression
            continue
        }
        return null
    }
}
