            if (path.endsWith("/")) {
                null
            } else {
                val zipFile = findContainingJarFile(url.toString()) ?: return URIFileContent(url, mimeResolve(url))
                JarFileContent(zipFile, path, mimeResolve(url)).takeIf { it.isFile }
