/** Wrap a procedure's output schema in the tRPC success envelope. tRPC HTTP responses are always serialised as:   `{ result: { data: T } }` When the procedure has no output the envelope is still present but the `data` property is omitted. */
function wrapInSuccessEnvelope(
  outputSchema: SchemaObject | null,
): SchemaObject {
  const hasOutput = outputSchema !== null && isNonEmptySchema(outputSchema);
  const resultSchema: SchemaObject = {
    type: 'object',
    properties: {
      ...(hasOutput ? { data: outputSchema } : {}),
    },
    ...(hasOutput ? { required: ['data'] } : {}),
  };
  return {
    type: 'object',
    properties: {
      result: resultSchema,
    },
    required: ['result'],
  };
}
