  chunk.viteMetadata!.importedCss.forEach((file) => {
    allFiles.push(file)
    if (!seenCss.has(file)) {
      seenCss.add(file)
      filteredFiles.push(file)
    }
  })

  analyzedImportedCssFiles.set(chunk, unique(allFiles))

  return filteredFiles
}
