```typescript
/** Compiles an exclusion like `MiddlewareConsumer.exclude()` does, except that the match is exact: case-sensitive (Fastify routes case-sensitively, so `/WEBHOOKS` may reach another route) and without an optional trailing slash (Fastify routes `/webhooks/` to `/webhooks/:id` with an empty `id`). */
function compileExclusion(
  path: string,
  requestMethod: RequestMethod,
  logs: boolean,
): ExcludeRouteMetadata {
  const converted = LegacyRouteConverter.tryConvert(path, { logs });
  const normalized =
    converted.length > 1 ? converted.replace(/\/+$/, '') : converted;
  return {
    path: normalized,
    requestMethod,
    pathRegex: pathToRegexp(addLeadingSlash(normalized) || '/', {
      sensitive: true,
      trailing: false,
    }).regexp,
  };
}
