/** Resolves the generated endpoint name for an operation by applying the configured {@linkcode OperationIdTransformer}. - `"camelCase"` *(default)* - delegates to `oazapfts`   {@linkcode getOperationName | getOperationName()}, which applies lodash   {@linkcode camelCase | camelCase()} and falls back to a verb+path derived   name when {@linkcode operation.operationId} is absent. - `"none"` - returns {@linkcode operation.operationId} verbatim. - `(operationId: string) => string` - calls the provided function with   {@linkcode operation.operationId}. For `"none"` and function transformers, a missing {@linkcode operation.operationId} throws an {@linkcode Error} with the offending HTTP method and path in the message. */
export function resolveOperationName(
  operationDefinition: Pick<OperationDefinition, 'verb' | 'path' | 'operation'>,
  operationIdTransformer: OperationIdTransformer = 'camelCase'
): string {
  const { verb, path, operation } = operationDefinition;

  if (operationIdTransformer === 'camelCase') {
