  struct _uv_barrier* b;

  if (barrier == NULL || count == 0)
    return UV_EINVAL;

  b = uv__malloc(sizeof(*b));
  if (b == NULL)
    return UV_ENOMEM;
#endif

  b->in = 0;
  b->out = 0;
  b->threshold = count;

  rc = uv_mutex_init(&b->mutex);
  if (rc != 0)
    goto error2;

  /* TODO(vjnash): remove these uv_cond_t casts in v2. */
  rc = uv_cond_init((uv_cond_t*) &b->cond);
  if (rc != 0)
    goto error;

#ifndef _WIN32
  barrier->b = b;
#endif
  return 0;

error:
  uv_mutex_destroy(&b->mutex);
error2:
#ifndef _WIN32
  uv__free(b);
#endif
  return rc;
}
