            case 0xCC:
            case 0xCD:
            case 0xCE:
            case 0xCF:
            case 0xD0:
            case 0xD1:
            case 0xD2:
            case 0xD3:
                found = "an integer";
                break;
            case 0xDC:
            case 0xDD:
                found = "an array";
                break;
            case 0xDE:
            case 0xDF:
                found = "a map";
                break;
            default:
                // fixint, fixmap, and fixarray; strings, EOF, and the unused
                // byte 0xC1 are left to get_msgpack_string
                if (current == char_traits<char_type>::eof())
