export function unregisterDefaultQueryClient(client: QueryClient): void {
  const count = registeredClients.get(client)
  if (count === undefined) {
    return
  }

  if (count > 1) {
    registeredClients.set(client, count - 1)
    return
  }

  registeredClients.delete(client)
  if (defaultClient !== client) {
