      'provenance',
      'package registry',
    ],
    migration: ['migration guide', 'breaking change', 'upgrade path'],
    architecture: ['api design', 'architecture decision', 'design pattern'],
  }

  for (const [category, categoryPhrases] of Object.entries(phrasePatterns)) {
