  } else {
    scope =
        context
                .getElementForInheritedWidgetOfExactType<
                  _UncontrolledProviderScope
                >()
                ?.widget
            as _UncontrolledProviderScope?;
  }

  if (scope == null) {
    throw StateError('No ProviderScope found');
  }

  return scope.container;
}
