def progress(count):
    items = range(count)

    def process_slowly(item):
        time.sleep(0.002 * random.random())

    def filter(items):
        for item in items:
            if random.random() > 0.3:
                yield item
    with click.progressbar(items, label='Processing accounts', fill_char=click.style('#', fg='green')) as bar:
        for item in bar:
            process_slowly(item)

    def show_item(item):
        if item is not None:
            return f'Item #{item}'
    with click.progressbar(filter(items), label='Committing transaction', fill_char=click.style('#', fg='yellow'), item_show_func=show_item) as bar:
        for item in bar:
            process_slowly(item)
    with click.progressbar(length=count, label='Counting', bar_template='%(label)s  %(bar)s | %(info)s', fill_char=click.style('█', fg='cyan'), empty_char=' ') as bar:
        for item in bar:
            process_slowly(item)
    with click.progressbar(length=count, width=0, show_percent=False, show_eta=False, fill_char=click.style('#', fg='magenta')) as bar:
