{
    var i = start;
    while (backward ? i >= 0 : i < formatString.Length)
    {
        var c = formatString[i];

        // Skip whitespace and common date-pattern punctuation (e.g., "25. MMMM", "25, MMMM").
        if (c is ' ' or '.' or ',' or '-' or '/')
        {
