/** Await for [desiredSpace] will be available for write and invoke [block] function providing [Memory] instance and the corresponding range suitable for wiring in the memory. The block function should return number of bytes were written, possibly 0. */
public suspend fun ByteWriteChannel.write(
    desiredSpace: Int = 1,
    block: (ByteArray, Int, Int) -> Int
): Int {
    val before = writeBuffer.size
    UnsafeBufferOperations.writeToTail(writeBuffer.buffer, desiredSpace, block)
    val after = writeBuffer.size
    val written = after - before
    flushIfNeeded()
    return written
}
