void uv_barrier_destroy(uv_barrier_t* barrier) {
#ifdef _WIN32
  uv_barrier_t* b;
  b = barrier;
#else
  struct _uv_barrier* b;
  b = barrier->b;
#endif

  uv_mutex_lock(&b->mutex);

  assert(b->in == 0);
  while (b->out != 0)
    uv_cond_wait((uv_cond_t*) &b->cond, &b->mutex);

  if (b->in != 0)
