/** The stack string usually contains a copy of the message at the start of the stack. If the stack starts with the message, we remove it and just return the stack trace portion. Otherwise the original stack trace is used. */
function extractStack(e: RollupError) {
  const { stack, name = 'Error', message } = e

  // If we don't have a stack, not much we can do.
  if (!stack) {
    return stack
  }

  const expectedPrefix = `${name}: ${message}\n`
  if (stack.startsWith(expectedPrefix)) {
    return stack.slice(expectedPrefix.length)
  }

  return stack
}
