/** Boots `module` on the given adapter and listens on an ephemeral port on 127.0.0.1. On Fastify, `@fastify/multipart` is registered by the adapter; `setup` runs before `app.init()`, `afterInit` between it and `listen()`. Listening explicitly matters: given a server that is not listening, supertest listens on port 0 of every interface (`::`), and on some systems another process can then hold the same port on 127.0.0.1, which is where supertest sends the request. */
export async function createApp(
  adapterName: AdapterName,
  module: Type<unknown>,
  options: {
    adapter?: FastifyAdapter;
    setup?: (app: NestFastifyApplication) => unknown;
    afterInit?: (app: NestFastifyApplication) => unknown;
  } = {},
): Promise<INestApplication> {
  const moduleRef = await Test.createTestingModule({
    imports: [module],
  }).compile();
  if (adapterName === 'express') {
    const app = moduleRef.createNestApplication(new ExpressAdapter());
    await app.listen(0, '127.0.0.1');
    return app;
  }
  const app = moduleRef.createNestApplication<NestFastifyApplication>(
    options.adapter ?? new FastifyAdapter(),
  );
