			name:           "not modified",
			method:         http.MethodGet,
			status:         http.StatusNotModified,
			wantNextCalled: true,
		},
		{
			name:        "head",
			method:      http.MethodHead,
			status:      http.StatusOK,
			wantErrors:  []string{"html renderer is not configured"},
			wantAborted: true,
