			assert.Equal(t, tt.wantErrors, contextErrors)
			assert.Equal(t, tt.wantAborted, contextAborted)
			assert.Equal(t, tt.wantNextCalled, nextHandlerCalled)
			assert.Empty(t, w.Body.String())
		})
	}
