dynamic _round(dynamic number) {
  if (number is num) {
    if (number.isInfinite) {
      return _maxInt;
    } else {
      return number.round();
    }
  } else if (number.remainder(1) == 0) {
    // Not a normal number, but int-like, e.g. Int64
    return number;
