```typescript
/** Dehydrates a single `Query` into a serializable `DehydratedQuery` snapshot. Note that most query config (e.g. `queryFn`, `staleTime`) is not dehydrated but instead meant to be configured again when consuming the de/rehydrated data, typically with `useQuery` on the client. If the query is still `pending`, its in-flight promise is dehydrated too so it can be resumed on the other side instead of re-fetched. */
export function dehydrateQuery(
  query: Query,
  serializeData?: TransformerFn,
  shouldRedactErrors?: (error: unknown) => boolean,
): DehydratedQuery {
  return {
    dehydratedAt: Date.now(),
    state: {
      ...query.state,
      ...(query.state.data !== undefined && {
        data: serializeData
          ? serializeData(query.state.data)
          : query.state.data,
      }),
    },
    queryKey: query.queryKey,
    queryHash: query.queryHash,
    ...(query.state.status === 'pending' && {
      promise: dehydratePromise(query, serializeData, shouldRedactErrors),
    }),
    ...(query.meta && { meta: query.meta }),
    ...(query.queryType && { queryType: query.queryType }),
  }
}
