/** Provides the `QueryClient` like `QueryClientProvider`, and restores the persisted client first: while restoring, `useIsRestoring` returns `true` and queries wait for the restore to finish before subscribing. Once restored, the client is saved with the persister whenever the cache changes. */
export const PersistQueryClientProvider = (
  props: PersistQueryClientProviderProps,
): JSX.Element => {
  const [isRestoring, setIsRestoring] = createSignal(true)

  const options = createMemo(() => ({
    ...props.persistOptions,
    queryClient: props.client,
  }))

  createEffect(() => {
    setIsRestoring(true)
    persistQueryClientRestore(options())
      .then(() => props.onSuccess?.())
      .catch(() => props.onError?.())
      .finally(() => {
        setIsRestoring(false)
      })
  })

  createEffect(() => {
    let unsubscribe = () => {}
    if (!isRestoring()) {
      unsubscribe = persistQueryClientSubscribe(options())
    }
    onCleanup(() => unsubscribe())
  })

  return (
    <QueryClientProvider client={props.client}>
      <IsRestoringProvider value={isRestoring}>
        {props.children}
